parameters.jsCode:
try {
  // Intentamos obtener los datos del output de la IA
  const data = $json.output;

  // Si 'data' no existe o está vacío, lanzamos un error manual para ir al catch
  if (!data || Object.keys(data).length === 0) {
    throw new Error("El output de la IA está vacío o no es un objeto");
  }

  return {
    puesto: data.puesto || "Puesto no detectado",
    empresa: data.empresa || "Empresa no detectada",
    link_vacante: data.link_vacante || "#",
    fecha_deteccion: data.fecha_deteccion || new Date().toISOString().split('T')[0],
    plataforma: data.plataforma || "Adzuna",
    estado: data.estado || "Pendiente",
    contacto: data.contacto || false,
    resumen_ia: data.resumen_ia || "Sin resumen disponible"
  };

} catch (error) {
  // Si algo sale mal, devolvemos un objeto de "emergencia" 
  // para que el flujo no se detenga y sepas que hubo un error
  return {
    puesto: "⚠️ ERROR DE PROCESAMIENTO",
    empresa: "Revisar logs de n8n",
    link_vacante: "#",
    fecha_deteccion: new Date().toISOString().split('T')[0],
    plataforma: "Error",
    estado: "Error",
    contacto: false,
    resumen_ia: "Hubo un problema parseando la respuesta de la IA: " + error.message
  };
}

